import csv, math, re
from datetime import datetime
from statistics import median
from collections import defaultdict

PATH='/app/dataset/data.csv'
DTFMT='%Y-%m-%dT%H:%M:%SZ'
Q4_START=datetime(2025,10,1,0,0,0)
Q4_END=datetime(2025,12,31,23,59,59)

items_re = re.compile(r'items=([+-]?\d+)')
adj_re = re.compile(r'adj=([+-]?\d+(?:\.\d+)?)%')
fee_re = re.compile(r'fee=([+-]?\d+(?:\.\d+)?)')
waive_re = re.compile(r'waive=true', re.I)

def parse_amount(raw, cr_mode='substring', paren_mode='enclosed'):
    s = raw.strip()
    if s == '':
        return math.nan
    u = s.upper()
    if cr_mode == 'substring':
        cr_neg = 'CR' in u
    else:
        cr_neg = bool(re.search(r'(?<![A-Z0-9])CR(?![A-Z0-9])', u))
    if paren_mode == 'enclosed':
        par_neg = s.startswith('(') and s.endswith(')')
    else:
        par_neg = ('(' in s and ')' in s)
    neg = cr_neg or ('-' in s) or par_neg
    u = u.replace('C1', '').replace('C2', '')
    clean = ''.join(ch for ch in u if ch.isdigit() or ch in ',.')
    if clean == '':
        return math.nan
    if ',' in clean and '.' in clean:
        if clean.rfind(',') > clean.rfind('.'):
            dec, thou = ',', '.'
        else:
            dec, thou = '.', ','
        int_part, frac = clean.rsplit(dec, 1)
        num = int_part.replace(thou, '') + '.' + frac
    elif ',' in clean or '.' in clean:
        sep = ',' if ',' in clean else '.'
        last = clean.rfind(sep)
        digits_after = len(clean) - last - 1
        if digits_after == 2:
            int_part = clean[:last].replace(sep, '')
            frac = clean[last+1:]
            num = int_part + '.' + frac
        else:
            num = clean.replace(sep, '')
    else:
        num = clean
    try:
        val = float(num)
    except ValueError:
        return math.nan
    return -abs(val) if neg else val


def parse_notes(notes):
    items_m = items_re.search(notes)
    adj_m = adj_re.search(notes)
    fee_m = fee_re.search(notes)
    items = int(items_m.group(1)) if items_m else None
    adj = float(adj_m.group(1))/100.0 if adj_m else 0.0
    fee = float(fee_m.group(1)) if fee_m else 0.0
    waive = bool(waive_re.search(notes))
    return items, adj, fee, waive


def compute(cr_mode='substring', paren_mode='enclosed', waive_nan_priority=True, dedup_before_filter=True):
    rows=[]
    with open(PATH, newline='') as f:
        r = csv.DictReader(f)
        for i,row in enumerate(r):
            base = parse_amount(row['amount_str'], cr_mode, paren_mode)
            items, adj, fee, waive = parse_notes(row['notes'])
            if math.isnan(base):
                net = math.nan
                if waive and not waive_nan_priority:
                    net = 0.0
            else:
                net = base * (1.0 + adj) + fee
                if waive:
                    net = 0.0
            et = row['event_time'].strip()
            dt = datetime.strptime(et, DTFMT) if et else None
            rows.append({
                'record_id': row['record_id'], 'event_time': dt, 'region': row['region'], 'channel': row['channel'],
                'items': items, 'net': net, 'file_order': i,
            })

    def dedup(rows):
        best={}
        for row in rows:
            rid=row['record_id']
            cur=best.get(rid)
            if cur is None:
                best[rid]=row; continue
            a,b=row['event_time'],cur['event_time']
            if a is None and b is not None:
                pass
            elif a is not None and b is None:
                best[rid]=row
            elif a is not None and b is not None and a > b:
                best[rid]=row
            elif a is not None and b is not None and a < b:
                pass
            else:
                a_real=not math.isnan(row['net'])
                b_real=not math.isnan(cur['net'])
                if a_real and not b_real:
                    best[rid]=row
                elif b_real and not a_real:
                    pass
                elif row['file_order'] < cur['file_order']:
                    best[rid]=row
        return list(best.values())

    def filt(rows):
        out=[]
        for row in rows:
            dt=row['event_time']
            if dt is None: continue
            if not (Q4_START <= dt <= Q4_END): continue
            if row['channel'].strip().lower() == 'phone': continue
            if not math.isfinite(row['net']): continue
            x=row.copy(); x['month']=dt.strftime('%Y-%m'); out.append(x)
        return out

    if dedup_before_filter:
        work = filt(dedup(rows))
    else:
        work = dedup(filt(rows))

    groups=defaultdict(list)
    for row in work:
        groups[(row['region'],row['month'])].append(row['net'])
    for row in work:
        vals=groups[(row['region'],row['month'])]
        med=median(vals)
        mad=median([abs(v-med) for v in vals])
        rz=0.0 if mad==0 else 0.6745*(row['net']-med)/mad
        items_eff=row['items'] if row['items'] is not None else 1
        if items_eff < 1: items_eff=1
        row['rz']=rz
        row['score']=abs(rz)*math.log1p(items_eff)
    ranked=sorted(work, key=lambda r: (-r['score'], -abs(r['rz']), -r['event_time'].timestamp(), r['record_id']))
    return [r['record_id'] for r in ranked[:10]]

variants = {
    'base': {},
    'cr_token': {'cr_mode':'token'},
    'paren_any_pair': {'paren_mode':'anypair'},
    'waive_overrides_nan': {'waive_nan_priority': False},
    'dedup_after_filter': {'dedup_before_filter': False},
}
for name, kwargs in variants.items():
    print(name, compute(**kwargs))
